import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CHISQUARE.md","filePath":"manual-zh/CHISQUARE.md","lastUpdated":1785684581000}'),o={name:"manual-zh/CHISQUARE.md"};function n(r,t,p,i,l,c){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h4 id="_15-12-2-卡方检验" tabindex="-1">15.12.2 卡方检验 <a class="header-anchor" href="#_15-12-2-卡方检验" aria-label="Permalink to &quot;15.12.2 卡方检验&quot;">​</a></h4><pre><code>     [ /CHISQUARE=var_list[(lo,hi)] [/EXPECTED={EQUAL|f1, f2 … fn}] ]
</code></pre><p><code>/CHISQUARE</code> 子命令对变量各分类的期望频数与观测频数之间的差异生成卡方统计量。可选地，变量列表后可出现一个取值范围。如果给定了范围，则非整数值会被截断，超出指定范围的值会被排除在分析之外。</p><p><code>/EXPECTED</code> 子命令指定每个类别的期望取值。对于每个观测类别，必须恰好有一个非零期望值，否则必须指定 <code>EQUAL</code> 关键字。你可以使用记法 <code>n*f</code> 来指定 n 个连续的期望类别，它们都取频率 f。给定的频率是比例，而非绝对频率。频率之和不必为 1。如果未给出 <code>/EXPECTED</code> 子命令，则期望各频率相等。</p><h4 id="_15-12-2-1-卡方示例" tabindex="-1">15.12.2.1 卡方示例 <a class="header-anchor" href="#_15-12-2-1-卡方示例" aria-label="Permalink to &quot;15.12.2.1 卡方示例&quot;">​</a></h4><p>一位研究者希望调查某总体中男女人数是否相等。所选择的调查样本来自 physiology.sav 数据集。该检验的零假设是总体中男女人数相等。分析过程如示例 15.5 所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  npar test      /chisquare=sex.</span></span></code></pre></div><p><strong>示例 15.5：</strong> 执行卡方检验以检查性别分布是否均衡</p><p>只有一个检验变量，即 <strong>sex</strong>（性别）。数据集中的其他变量被忽略。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 15.4：</strong> 使用图形用户界面执行卡方检验</p><p>在结果 15.4 的汇总框中显示，样本中男性多于女性。然而卡方结果的显著性大于 0.05——这是最常被接受的 p 值——因此没有足够证据拒绝零假设，只能得出证据并不表明总体中存在性别失衡的结论。</p><table tabindex="0"><thead><tr><th>Value</th><th>Observed N</th><th>Expected N</th><th>Residual</th></tr></thead><tbody><tr><td>Male</td><td>22</td><td>20.00</td><td>2.00</td></tr><tr><td>Female</td><td>18</td><td>20.00</td><td>-2.00</td></tr><tr><td>Total</td><td>40</td><td></td><td></td></tr><tr><td></td><td>Chi-square</td><td>df</td><td>Asymp. Sig.</td></tr><tr><td>Sex of subject</td><td>.40</td><td>1</td><td>.527</td></tr></tbody></table><p><strong>结果 15.4：</strong> 对 <strong>sex</strong>（性别）运行卡方检验的结果</p>`,14)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
